interface.signature:
interface WorkerStatus {
  hostname: string;
  status: 'active' | 'idle' | 'unresponsive';
  uptime_seconds: number;
  active_tasks: number;
  completed_tasks: number;
  cpu_percent: number;
  memory_percent: number;
  throughput_per_minute: number;
}

interface WorkerRestartResponse {
  success: boolean;
  message: string;
}

restartWorker: async (hostname: string): Promise<WorkerRestartResponse> => {
  const response = await apiClient.post<WorkerRestartResponse>(`/api/v1/workers/${hostname}/restart`);
  return response.data;
}

export const useRestartWorker = () => {
  const queryClient = useQueryClient();
  return useMutation<WorkerRestartResponse, Error, string>({
    mutationFn: workersApi.restartWorker,
    onSuccess: (data, hostname) => {
      queryClient.invalidateQueries({ queryKey: workerKeys.lists() });
      toast.success(`Worker ${hostname} restart initiated`);
    },
    onError: (error, hostname) => {
      toast.error(`Failed to restart worker ${hostname}`);
    },
  });
};

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title?: string;
  description?: string;
  children: ReactNode;
  footer?: ReactNode;
  size?: 'sm' | 'md' | 'lg' | 'xl';  // Use 'md' for restart dialog
  preventBackdropClose?: boolean;
  className?: string;
  showCloseButton?: boolean;
}
